/*
 * textures.c -- the eight Wave Race 64 sea textures, embedded.
 *
 * Derived from the unsigned int sot_sea_*[1024] arrays
 *
 * Each is 32 by 32, one texel per four bytes in the N64's R G B A
 * order, which is byte for byte what the ROM holds. The original
 * declares them unsigned int[32*32]; these are the same words as bytes,
 * so the data carries no endianness of its own and r_texture_upload
 * does the swizzle to A8R8G8B8.
 *
 * Each course selects one of these through crs_sea[]; there is no
 * per-course tint constant. plan.txt section 9.3.
 */

